import{d as r,C as a,o as g,c as h,a3 as i,E as e,j as s,a as d}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"正易心法·后序与跋","description":"《正易心法》后序（李潜）与跋（戴师愈）：李潜得书于庐山，为之辨真伪、许以「一滴千金」「物外真仙之书」；戴师愈以麻衣识三天子气、判钱若水无仙骨二事，证其识见之非凡。","frontmatter":{"title":"正易心法·后序与跋","description":"《正易心法》后序（李潜）与跋（戴师愈）：李潜得书于庐山，为之辨真伪、许以「一滴千金」「物外真仙之书」；戴师愈以麻衣识三天子气、判钱若水无仙骨二事，证其识见之非凡。","category":"guide","aliases":["正易心法后序","正易心法跋","李潜戴师愈"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/postscript.md","filePath":"yijing/zheng-yi-xin-fa/postscript.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/postscript.md"},x=r({...c,setup(u){const t=[{id:"ps-01",label:"一、得之庐山",showLabel:!0,sentences:[["麻衣道者《羲皇氏正易心法》，",{text:"顷",glossary:"qing"},"得之",{text:"庐山一异人",glossary:"lushanYiyiren"},"。或云许坚。或有疑而问者，余应之云：“何疑之有？顾其议论可也。”"]],note:["麻衣道者的《羲皇氏正易心法》，是我不久前从庐山一位奇异之人那里得到的，有人说那人是许坚。有人对此书的真伪有所怀疑，我回答说：「有什么好怀疑的？只看它的议论内容就好了。」（**李潜的态度很醒豁**：**不问作者是谁，先看议论如何。** 这是读书人最难的一种清醒——**不拜名字，只认内容。**）"]},{id:"ps-02",label:"二、素问与大传",showLabel:!0,sentences:[["昔",{text:"皇帝",glossary:"huangdi"},"《",{text:"素问",glossary:"suwen"},"》，孔子《",{text:"易大传",glossary:"yidazhuan"},"》，世尚有疑之，尝曰：世固有能作《素问》者乎？固有能作《易大传》者乎？虽非本真，亦皇帝、孔子之",{text:"徒",glossary:"tu"},"也。"]],note:["昔日黄帝的《素问》、孔子的《易大传》，世上也有人怀疑其真伪，曾有人说：「世上真的有人能写出《素问》吗？真的有人能写出《易大传》吗？」即使不是本人所作，也是黄帝、孔子一脉的传人所作。（**李潜用一个现成的先例为自己解围**：**连《素问》《易大传》都有人怀疑，何况《正易心法》？** 而他的回答很豁达：**「虽非本真，亦黄帝孔子之徒」——真假之外，还有一脉相承这回事。**）"]},{id:"ps-03",label:"三、麻衣之徒",showLabel:!0,sentences:[["余于《正易心法》，亦曰：世固能有作之者乎？虽非麻衣，是乃麻衣之",{text:"街徒",glossary:"jietu"},"也。胡不观其文辞议论乎？"]],note:["我对《正易心法》也这样说：世上真的有人能写出这本书吗？即使不是麻衣本人，也是麻衣一脉的传人所为。为什么不看它的文辞议论呢？（**李潜的论证方式很漂亮**：**能写出这样的议论的人，本身就已经是「麻衣之徒」了**——**真假之辨，在「能不能写出」这件事上自动失效。** 原文「街徒」疑为「嫡徒」或「私徒」之讹。）"]},{id:"ps-04",label:"四、一滴千金",showLabel:!0,sentences:[["一滴千金，源流天造，前无古人，后无来者。翩然于羲皇心地",{text:"弛聘",glossary:"chicheng"},"，实物外",{text:"真仙之书",glossary:"zhenxianZhishu"},"也。"]],note:["一滴值千金，源头是天造；前无古人，后无来者。轻快地在羲皇心地上驰骋，实在是超越世俗的真仙之书。（**「一滴千金，源流天造」八字分量极重**——**「天造」不是夸奖，是把这本书放回了它自己的源头：它不是人造的，是自然流露的。** 这也正是麻衣在第二十章、第二十八章反复说的「本之自然」。原文「弛聘」当作「驰骋」；「于羲皇心地驰骋」正呼应第四十一章末句。）"]},{id:"ps-05",label:"五、读书十年",showLabel:!0,sentences:[["读书十年方悟，",{text:"浸渍触类",glossary:"jinziChulei"},"，以知《易》道之大如是也。",{text:"得其人，当与共之",glossary:"deqiren"},"。崇宁三年三月九日，",{text:"庐峰隐者李潜几道",glossary:"liqianJidao"},"书。"]],note:["我读了十年才领悟，浸泡其中、触类旁通，才知道《易》道之大如此。遇到合适的人，应当与之共享。崇宁三年三月九日，庐峰隐者李潜（字几道）书。（**「读书十年方悟」是全书最好的一个注脚**：麻衣在第四十一章说「要须自悟」，**李潜用十年给出了一个真实的回应**——**不是某一天突然开窍，而是十年里一点一点、在无数个「触类」的瞬间慢慢积累。** 而「浸渍」二字尤妙：**不是强攻，是让它慢慢渗透。**）"]},{id:"ps-06",label:"六、三天子气",showLabel:!0,sentences:[["五代",{text:"李守正",glossary:"lishouzheng"},"叛河中，",{text:"周太祖",glossary:"zhoutaizu"},"亲征。麻衣语",{text:"赵韩王",glossary:"zhaohanwang"},"曰：“李侍中安得久？其城中有",{text:"三天子气",glossary:"santianziqi"},"。”末岁，城陷。时",{text:"周世宗",glossary:"zhoushizong"},"与",{text:"宋朝太祖",glossary:"songtaizu"},"侍行。"]],note:["五代时，李守正（一作李守贞）在河中府叛乱，后周太祖郭威亲自出征。麻衣对赵匡胤（时封韩王）说：「李侍中能撑多久？他的城中有三个天子的气象。」后来城池陷落。当时后周世宗柴荣和宋朝太祖赵匡胤都随行出征。（**这一句「三天子气」是一段极精准的预言**：郭威已是天子，柴荣是未来的天子，赵匡胤是更远未来的天子——**麻衣在公元 950 年前后，同时看见了这三个人。**）"]},{id:"ps-07",label:"七、钱若水无仙骨",showLabel:!0,sentences:[[{text:"钱文僖公若水",glossary:"qianruoshui"},"，",{text:"陈希夷",glossary:"chenxizhen"},"每见，以其",{text:"神观清粹",glossary:"shenguanQingcui"},"，谓可学仙，有",{text:"升举之分",glossary:"shengjuZhifen"},"。见之未精，使麻衣决之。麻衣云：“",{text:"无仙骨",glossary:"wuxiangu"},"，但可作",{text:"贵公卿",glossary:"guigongqing"},"耳。”"]],note:["钱文僖公钱若水，陈希夷每次见到他，因为他神态气质清澈纯粹，认为他可以学仙，有升仙的缘分；但陈希夷自觉看得不够精准，就让麻衣来做最终判断。麻衣说：「没有仙骨，只能做高贵的公卿大臣罢了。」（**这一则的分量在于「比较」**：**陈希夷本人就是著名道士、相术大家**，他看钱若水，看出「有升举之分」；**但他自觉不精，请麻衣决之**。**麻衣一眼断下：「无仙骨，但可作贵公卿。」** 后来钱若水官至枢密副使，果然只是「贵公卿」——**连内行都看不准的，他一眼看准。**）"]},{id:"ps-08",label:"八、识人之准",showLabel:!0,sentences:[["夫以神仙与帝王之相，岂可识哉？麻衣一见决之，则其识为何如也？即其识神仙、识帝王眼目以论《易》，则其出于寻常万一也，固不容于其言矣。乾道元年冬十有一月初七曰，",{text:"玉溪戴师愈孔文",glossary:"daishiyu"},"撰。"]],note:["神仙与帝王的气象，哪里是一般人能识别的？麻衣一见就能判断，他的见识是何等境界？正是凭借这种识别神仙、识别帝王的眼光来论《易》，他的见识远超寻常万倍，当然不能轻视他的话。乾道元年冬十一月初七日，玉溪戴师愈（字孔文）撰。（**戴师愈的策略很清楚**：**李潜从句「文本」立论，戴师愈从句「人物」立论**——一个说「内容本身就是证明」，一个说「这样的人论《易》，岂是寻常」。**两篇合读，互相补充。**）"]}],p=[{id:"qing",term:"顷",pinyin:"qǐng",meaning:"不久前。李潜说他近来得到此书。"},{id:"lushanYiyiren",term:"庐山一异人",pinyin:"lú shān yī yì rén",meaning:"庐山的一位奇异之人，即传书者；名或为许坚。"},{id:"huangdi",term:"皇帝",pinyin:"huáng dì",meaning:"当作「黄帝」，传抄之讹。《黄帝内经·素问》的托名作者。"},{id:"suwen",term:"素问",pinyin:"sù wèn",meaning:"《黄帝内经·素问》。世人也曾怀疑其真伪。"},{id:"yidazhuan",term:"易大传",pinyin:"yì dà zhuàn",meaning:"孔子《易大传》（十翼）。同样有人怀疑是否真为孔子所作。"},{id:"tu",term:"徒",pinyin:"tú",meaning:"一脉的传人。即使非本人所作，也是同道传人。"},{id:"jietu",term:"街徒",pinyin:"jiē tú",meaning:"疑为「嫡徒」或「私徒」之讹，意为麻衣一脉的传人。"},{id:"chicheng",term:"弛聘",pinyin:"chí chěng",meaning:"当作「驰骋」，传抄之讹。呼应第四十一章「于羲皇心地上驰骋」。"},{id:"zhenxianZhishu",term:"真仙之书",pinyin:"zhēn xiān zhī shū",meaning:"超越世俗的真仙之书。李潜对此书的最高评价。"},{id:"jinziChulei",term:"浸渍触类",pinyin:"jìn zì chù lèi",meaning:"浸泡其中，触类旁通。李潜读书十年的方法。"},{id:"deqiren",term:"得其人当与共之",pinyin:"dé qí rén",meaning:"遇到合适的人，应当与之分享。此书非人人可读，要看缘分。"},{id:"liqianJidao",term:"李潜几道",pinyin:"lǐ qián jǐ dào",meaning:"后序作者。李潜，字几道，号庐峰隐者。崇宁三年（1104）作。"},{id:"lishouzheng",term:"李守正",pinyin:"lǐ shǒu zhèng",meaning:"当作「李守贞」，五代时叛于河中府。"},{id:"zhoutaizu",term:"周太祖",pinyin:"zhōu tài zǔ",meaning:"后周太祖郭威，亲自出征李守贞。"},{id:"zhaohanwang",term:"赵韩王",pinyin:"zhào hán wáng",meaning:"赵匡胤，时封韩王，即后来的宋太祖。"},{id:"santianziqi",term:"三天子气",pinyin:"sān tiān zǐ qì",meaning:"城中（军中）有三个天子的气象：郭威、柴荣、赵匡胤。"},{id:"zhoushizong",term:"周世宗",pinyin:"zhōu shì zōng",meaning:"后周世宗柴荣，当时随行。"},{id:"songtaizu",term:"宋朝太祖",pinyin:"sòng tài zǔ",meaning:"赵匡胤，宋朝开国之君，当时随行。"},{id:"qianruoshui",term:"钱文僖公若水",pinyin:"qián ruò shuǐ",meaning:"钱若水，谥文僖，北宋名臣，后官至枢密副使。"},{id:"chenxizhen",term:"陈希夷",pinyin:"chén xī yí",meaning:"陈抟，字图南，号希夷，麻衣道者的传人。"},{id:"shenguanQingcui",term:"神观清粹",pinyin:"shén guān qīng cuì",meaning:"神态气质清澈纯粹，有仙家气质。"},{id:"shengjuZhifen",term:"升举之分",pinyin:"shēng jǔ zhī fèn",meaning:"得道升仙的缘分。道家术语。"},{id:"wuxiangu",term:"无仙骨",pinyin:"wú xiān gǔ",meaning:"没有成仙的骨相。相术术语。"},{id:"guigongqing",term:"贵公卿",pinyin:"guì gōng qīng",meaning:"高贵的公卿大臣。钱若水后来官至枢密副使，果如所言。"},{id:"daishiyu",term:"戴师愈孔文",pinyin:"dài shī yù kǒng wén",meaning:"跋作者。戴师愈，字孔文，号玉溪。乾道元年（1165）撰。"}];return(m,n)=>{const l=a("DaoTextReading"),o=a("DaoKeywordCards");return g(),h("div",null,[n[0]||(n[0]=i(`<h1 id="正易心法·后序与跋" tabindex="-1">正易心法·后序与跋 <a class="header-anchor" href="#正易心法·后序与跋" aria-label="Permalink to &quot;正易心法·后序与跋&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>后序与跋都<strong>不是麻衣所作</strong>，是两位读者留下的文字：</p><table tabindex="0"><thead><tr><th>篇</th><th>作者</th><th>时间</th><th>性质</th></tr></thead><tbody><tr><td><strong>后序</strong></td><td>李潜（几道）</td><td>崇宁三年（1104）</td><td>读后感：为真伪辩护，给出最高评价</td></tr><tr><td><strong>跋</strong></td><td>戴师愈（孔文）</td><td>乾道元年（1165）</td><td>历史考证 + 人物评传</td></tr></tbody></table><p><strong>两篇的立论方式恰好互补</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>李潜（从「文本」立论）：不必纠结作者真伪，看议论内容就好</span></span>
<span class="line"><span>                       此书「一滴千金」「源物外真仙之书」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>戴师愈（从「人物」立论）：麻衣能识帝王、识神仙</span></span>
<span class="line"><span>                         这样的人论《易》，岂是寻常？</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「三天子气」的历史还原</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间：公元 950 年前后    地点：河中府（今山西运城）</span></span>
<span class="line"><span>事件：李守贞叛乱，后周太祖郭威亲征</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在场三人：</span></span>
<span class="line"><span>  郭威（后周太祖）  = 第一个天子</span></span>
<span class="line"><span>  柴荣（后周世宗）  = 第二个天子</span></span>
<span class="line"><span>  赵匡胤（宋太祖）  = 第三个天子</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的预言：「其城中有三天子气。」</span></span>
<span class="line"><span>= 他不是说李守贞城里有三个天子</span></span>
<span class="line"><span>  而是说来打你的这支军队里，有三个人将来会成为天子</span></span></code></pre></div><p><strong>「钱若水无仙骨」的故事</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>陈希夷看钱若水：「神观清粹，可学仙，有升举之分」</span></span>
<span class="line"><span>陈希夷自觉不够准 → 请麻衣来看</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣看钱若水：「无仙骨，但可作贵公卿耳。」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结果：钱若水官至枢密副使，是北宋著名政治家——果然是「贵公卿」，没有成仙</span></span>
<span class="line"><span>= 连陈希夷（著名道士、相术大家）都看不准的，麻衣一眼就看准了</span></span></code></pre></div><p><strong>「读书十年方悟」是全书最好的注脚</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>麻衣（第四十一章）：「要须自悟」</span></span>
<span class="line"><span>李潜（后序）：「读书十年方悟，浸渍触类」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>「浸渍」 = 浸泡在里面，不是强行理解，是等它自然渗入</span></span>
<span class="line"><span>「触类」 = 在日常生活中，忽然发现和书里说的对上了</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 这种「悟」不是某一天突然开窍</span></span>
<span class="line"><span>  而是十年里一点一点、在无数个「触类」的瞬间慢慢积累而成</span></span></code></pre></div><p><strong>「得其人，当与共之」——什么是「其人」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是读书多的人（读书多反而容易「袭谬承误」）</span></span>
<span class="line"><span>不是聪明的人（聪明反而容易「溺其辞」）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>而是：愿意「浸渍」的人、愿意「触类」的人、愿意「自悟」的人</span></span>
<span class="line"><span>= 一个有耐心、有感知、有自悟能力的人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>李潜读了十年，才敢说自己是「其人」</span></span>
<span class="line"><span>他写这篇后序，是在说：</span></span>
<span class="line"><span>  我找到了这本书，花了十年成为了「其人」，</span></span>
<span class="line"><span>  现在我把它传出去，等待下一个「其人」。</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读后序——<strong>「何疑之有？顾其议论可也」是最醒豁的一句</strong>；</li><li>再读跋——<strong>两个识人故事，是「有师承」的证明</strong>；</li><li>最后读「得其人，当与共之」——<strong>这句话现在轮到你来传了。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>得之庐山</strong>：李潜从庐山异人处得书。</li><li><strong>何疑之有</strong>：只看议论内容。</li><li><strong>素问大传</strong>：即使非本人所作，也是同道传人。</li><li><strong>一滴千金</strong>：源流天造，前无古人后无来者。</li><li><strong>读书十年</strong>：浸渍触类，方悟《易》道之大。</li><li><strong>得其人当与共之</strong>：等待下一个「其人」。</li><li><strong>三天子气</strong>：郭威、柴荣、赵匡胤。</li><li><strong>钱若水无仙骨</strong>：果为贵公卿。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,20)),e(l,{colophon:"得之庐山 · 一滴千金 · 读书十年 · 三天子气",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法后序与跋",sections:t,glossary:p}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入。原文数处疑有传抄之讹：「皇帝」当作「黄帝」、「弛聘」当作「驰骋」、「李守正」当作「李守贞」、「街徒」疑为「嫡徒」或「私徒」，以上说明而不径改。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[d("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"顾其议论可也",pinyin:["gù","qí"],meaning:"李潜的读书态度：不必纠结作者真伪，只看议论内容——不拜名字，只认内容。"},{term:"一滴千金",pinyin:["yī","dī"],meaning:"「源流天造」——不是夸奖，是把这本书放回它自己的源头：非人造，是自然流露。"},{term:"读书十年方悟",pinyin:["dú","shū"],meaning:"对麻衣「要须自悟」最真实的注脚。「浸渍」不是强攻，是让它慢慢渗透。"},{term:"得其人当与共之",pinyin:["dé","qí"],meaning:"「其人」＝有耐心、有感知、有自悟能力的人——李潜读了十年，才敢说自己是。"},{term:"三天子气",pinyin:["sān","tiān"],meaning:"郭威、柴荣、赵匡胤三人皆在军中——麻衣于公元 950 年同时看见这三人的命运。"},{term:"钱若水无仙骨",pinyin:["qián","ruò"],meaning:"连陈希夷都看不准的，麻衣一眼决之：无仙骨，但可作贵公卿——后果官至枢密副使。"}]}),n[3]||(n[3]=i(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>后序与跋都不是麻衣所作，是两位读者的文字：<strong>李潜从句「文本」立论</strong>（不必纠结真伪，看议论就好），<strong>戴师愈从句「人物」立论</strong>（麻衣能识帝王神仙，这样的人论《易》岂是寻常）。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「读书十年方悟」是全书最好的注脚</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>麻衣（第四十一章）：「要须自悟」</span></span>
<span class="line"><span>李潜（后序）：「读书十年方悟，浸渍触类」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>「浸渍」＝浸泡、自然渗入；「触类」＝日常中忽然对上</span></span>
<span class="line"><span>= 不是某一天突然开窍，是十年里一点一点积累</span></span></code></pre></div><p><strong>「得其人，当与共之」——什么是「其人」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是读书多的人（容易「袭谬承误」）</span></span>
<span class="line"><span>不是聪明的人（容易「溺其辞」）</span></span>
<span class="line"><span>而是：愿意浸渍、愿意触类、愿意自悟的人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>李潜读了十年，才敢说自己是「其人」</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>先读后序——<strong>「何疑之有？顾其议论可也」是最醒豁的一句</strong>；</li><li>再读跋——<strong>两个识人故事，是「有师承」的证明</strong>；</li><li>顺着钩子想：<strong>这本书在等什么样的人？</strong> 我的看法：<strong>李潜说得很清楚：「其人」不是读书最多的人，而是愿意用十年「浸渍」的人。</strong> 麻衣写了四十二章，<strong>李潜读了十年，戴师愈又写了一篇跋，然后这本书又沉默地等了几百年——</strong> <strong>它等的那个人，不是读完它的人，而是被它改变的人。</strong> 这句话现在轮到你来接了。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>麻衣道者的《羲皇氏正易心法》，是我不久前从庐山一位奇异之人那里得到的，有人说那人是许坚。有人对此书的真伪有所怀疑，我回答说：「有什么好怀疑的？只看它的议论内容就好了。」</p><p>昔日黄帝的《素问》、孔子的《易大传》，世上也有人怀疑其真伪，曾有人说：「世上真的有人能写出《素问》吗？真的有人能写出《易大传》吗？」即使不是本人所作，也是黄帝、孔子一脉的传人所作。</p><p>我对《正易心法》也这样说：世上真的有人能写出这本书吗？即使不是麻衣本人，也是麻衣一脉的传人所为。为什么不看它的文辞议论呢？</p><p>一滴值千金，源头是天造；前无古人，后无来者。轻快地在羲皇心地上驰骋，实在是超越世俗的真仙之书。</p><p>我读了十年才领悟，浸泡其中、触类旁通，才知道《易》道之大如此。遇到合适的人，应当与之共享。崇宁三年三月九日，庐峰隐者李潜（字几道）书。</p><p>五代时，李守贞在河中府叛乱，后周太祖郭威亲自出征。麻衣对赵匡胤（时封韩王）说：「李侍中能撑多久？他的城中有三个天子的气象。」后来城池陷落。当时后周世宗柴荣和宋朝太祖赵匡胤都随行出征。</p><p>钱文僖公钱若水，陈希夷每次见到他，因为他神态气质清澈纯粹，认为他可以学仙，有升仙的缘分。但陈希夷自觉看得不够精准，就让麻衣来做最终判断。麻衣说：「没有仙骨，只能做高贵的公卿大臣罢了。」</p><p>神仙与帝王的气象，哪里是一般人能识别的？麻衣一见就能判断，他的见识是何等境界？正是凭借这种识别神仙、识别帝王的眼光来论《易》，他的见识远超寻常万倍，当然不能轻视他的话。乾道元年冬十一月初七日，玉溪戴师愈（字孔文）撰。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：书的最后两页不是麻衣写的，是两个读者写的——<strong>一个说「我看的是内容」，一个说「我看的是这个人」。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「何疑之有？顾其议论可也」</strong>——<strong>这是全书最醒豁的一句读书态度</strong>：<strong>不拜名字，只认内容。</strong> 李潜不知道作者是谁，他也不在乎——<strong>能写出这样的议论，这就是证明。</strong></li><li><strong>「虽非麻衣，是乃麻衣之徒也」</strong>——<strong>这句话把真伪之辨化解掉了</strong>：<strong>能写出这样的东西的人，本身就是「麻衣之徒」。</strong> 身份不是靠传承证明的，是靠作品证明的。</li><li><strong>「一滴千金，源流天造」</strong>——注意「天造」这个词：<strong>不是夸奖，是把书放回它自己的源头。</strong> 它不人造的，是自然流露——这正是麻衣反复说的「本之自然」。</li><li><strong>「读书十年方悟」</strong>——<strong>这是全书最好的注脚</strong>。麻衣说「要须自悟」，李潜用十年回应了他。<strong>「浸渍」二字尤妙：不是强攻，是等它渗进来。</strong></li><li><strong>「得其人，当与共之」</strong>——李潜读了十年才敢说自己是「其人」。<strong>他写这篇后序，就是把这个接力棒交出去。</strong></li><li><strong>跋的两个故事</strong>——三天子气、钱若水无仙骨。<strong>戴师愈不是在讲传奇，是在为这本书做背书</strong>：<strong>能一眼看穿帝王与仙骨的人，他写的《易》论，岂是寻常？</strong></li><li><strong>留给自己的问题</strong>：<strong>这本书在等什么样的人？</strong> 我的看法：<strong>李潜说得很清楚：不是读书最多的人，而是愿意用十年「浸渍」的人。</strong> 麻衣写了四十二章，李潜读了十年，戴师愈又写了一篇跋，<strong>然后这本书又沉默地等了几百年——</strong> <strong>它等的那个人，不是读完它的人，而是被它改变的人。</strong> 这句话，现在轮到你来接了。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/preface">前序 · 陈抟传记</a> — 全书之前的陈抟传记</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-41">第四十一章 · 九流可入</a> — 「要须自悟」「于羲皇心地上驰骋」（后序「读书十年方悟」正回应此）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-42">第四十二章 · 舛讹为多</a> — 「呜乎」（正文的收尾，本页是全书最后两页）</li></ul>`,25))])}}});export{b as __pageData,x as default};
